private enum class RpsScreen{INFO,SEARCH,GAME,ERROR}
private fun rpsErrorMessage(e:Exception):String{if(e is HttpException){val body=runCatching{e.response()?.errorBody()?.string()}.getOrNull()?.replace("\n"," ")?.take(260);return if(body.isNullOrBlank())"HTTP ${e.code()} — السيرفر لم يرسل تفاصيل" else "HTTP ${e.code()}\n$body"};val detail=e.message?.take(260)?:e.javaClass.simpleName;return "${e.javaClass.simpleName}\n$detail"}

@Composable private fun RockPaperScissors(auth:String,onArenaChanged:(Boolean)->Unit,onBack:()->Unit){var screen by remember{mutableStateOf(RpsScreen.INFO)};var sessionId by remember{mutableStateOf<String?>(null)};var game by remember{mutableStateOf(RpsStateDto())};var error by remember{mutableStateOf("")};var busy by remember{mutableStateOf(false)};val scope=rememberCoroutineScope();val matchStartTone=remember{ToneGenerator(AudioManager.STREAM_MUSIC,90)}
 LaunchedEffect(screen){onArenaChanged(screen==RpsScreen.SEARCH||screen==RpsScreen.GAME)};DisposableEffect(Unit){onDispose{matchStartTone.release();onArenaChanged(false)}}
 LaunchedEffect(screen){if(screen==RpsScreen.SEARCH){try{error="";var match=rpsLiveApi.matchQueue(auth,MatchQueueRequest("ONE_V_ONE"));while(isActive&&screen==RpsScreen.SEARCH){if(match.state=="MATCHED"&&match.sessionId!=null){sessionId=match.sessionId;game=rpsLiveApi.state(auth,match.sessionId);matchStartTone.startTone(ToneGenerator.TONE_PROP_ACK,450);screen=RpsScreen.GAME;break};delay(1200);match=rpsLiveApi.matchStatus(auth)}}catch(e:CancellationException){throw e}catch(e:Exception){error=rpsErrorMessage(e);screen=RpsScreen.ERROR}}}
 LaunchedEffect(screen,sessionId){val id=sessionId?:return@LaunchedEffect;if(screen==RpsScreen.GAME)while(isActive&&screen==RpsScreen.GAME){delay(700);try{game=rpsLiveApi.state(auth,id)}catch(e:CancellationException){throw e}catch(_:Exception){}}}
 LaunchedEffect(screen,sessionId,game.phase,game.round,game.readyForNext){val id=sessionId?:return@LaunchedEffect;if(screen==RpsScreen.GAME&&game.phase=="RESULT"&&!game.readyForNext){delay(1000);try{game=rpsLiveApi.next(auth,id)}catch(e:CancellationException){throw e}catch(e:Exception){error=rpsErrorMessage(e)}}}
 Column(Modifier.fillMaxSize().background(ChallengeBg).padding(20.dp),horizontalAlignment=Alignment.CenterHorizontally){Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){if(screen==RpsScreen.INFO)Text("‹",color=ChallengeWhite,fontSize=36.sp,modifier=Modifier.clickable{onBack()})else if(screen==RpsScreen.SEARCH)Text("‹",color=ChallengeWhite,fontSize=36.sp,modifier=Modifier.clickable{if(!busy)scope.launch{busy=true;try{rpsLiveApi.cancelQueue(auth)}catch(_:Exception){};screen=RpsScreen.INFO;sessionId=null;busy=false}})else if(screen==RpsScreen.ERROR)Text("‹",color=ChallengeWhite,fontSize=36.sp,modifier=Modifier.clickable{screen=RpsScreen.INFO;sessionId=null});Spacer(Modifier.weight(1f));if(screen!=RpsScreen.INFO)Text("حجر ورقة مقص",color=ChallengeWhite,fontWeight=FontWeight.Bold,fontSize=20.sp)};Spacer(Modifier.weight(1f));when(screen){RpsScreen.INFO->Info{screen=RpsScreen.SEARCH};RpsScreen.SEARCH->Search();RpsScreen.ERROR->{AliqoArenaIcon(AliqoIcon.AVOID,size=62.dp);Text("تشخيص بدء المواجهة",color=ChallengeMuted,fontSize=14.sp);Spacer(Modifier.height(8.dp));Text(error,color=ChallengeWhite,fontSize=17.sp,textAlign=TextAlign.Center);Spacer(Modifier.height(20.dp));Button(onClick={screen=RpsScreen.SEARCH},colors=ButtonDefaults.buttonColors(containerColor=ChallengePurple)){Text("إعادة المحاولة")}};RpsScreen.GAME->{val id=sessionId!!;if(!game.opponentOnline&&!game.finished){OpponentOffline(game.opponentReconnectSeconds);Spacer(Modifier.height(18.dp))};when(game.phase){"PLAY"->LivePlay(game){move->if(!busy)scope.launch{busy=true;try{game=rpsLiveApi.move(auth,id,RpsMoveRequest(move))}catch(e:CancellationException){throw e}catch(e:Exception){error=rpsErrorMessage(e)};busy=false}};"WAITING"->WaitChoice(game.myMove);"RESULT"->LiveResult(game);"FINISHED"->LiveFinished(game,{scope.launch{busy=true;try{game=rpsLiveApi.rematch(auth,id)}catch(e:CancellationException){throw e}catch(e:Exception){error=rpsErrorMessage(e)};busy=false}},{onArenaChanged(false);onBack()});else->CircularProgressIndicator(color=ChallengePurple)}}};if(error.isNotBlank()&&screen==RpsScreen.GAME){Spacer(Modifier.height(12.dp));Text(error,color=Color(0xFFFF9A9A),fontSize=12.sp,textAlign=TextAlign.Center)};Spacer(Modifier.weight(1f))}}

