@Composable private fun LiveFinished(g:RpsStateDto,replay:()->Unit,back:()->Unit){val draw=g.myScore==g.opponentScore&&!g.endedByDisconnect;val won=g.wonMatch||(!draw&&g.myScore>g.opponentScore);AliqoArenaIcon(if(won)AliqoIcon.TROPHY else AliqoIcon.SWORDS,size=78.dp);Text(if(g.endedByDisconnect&&won)"انتصار بانسحاب الخصم" else if(g.endedByDisconnect)"انتهت المواجهة" else if(won)"انتصار" else if(draw)"تعادل" else "انتهت المواجهة",color=if(won)Color(0xFFFFC928)else if(draw)Color(0xFFFFD66B)else ChallengeWhite,fontSize=34.sp,fontWeight=FontWeight.Bold,textAlign=TextAlign.Center);ResultScore(g,34);Text(if(g.endedByDisconnect&&won)"لم يعد الخصم خلال مهلة الاتصال" else if(g.endedByDisconnect)"انتهت المواجهة بسبب الانقطاع" else if(won)"جمعت نقاطًا أكثر وفزت بالمواجهة" else if(draw)"انتهت الجولات العشر بالتعادل" else "جمع الخصم نقاطًا أكثر",color=ChallengeMuted,textAlign=TextAlign.Center);Spacer(Modifier.height(30.dp));Button(replay,Modifier.fillMaxWidth().height(54.dp),enabled=!g.rematchRequestedByMe,colors=ButtonDefaults.buttonColors(containerColor=ChallengePurple,disabledContainerColor=Color(0xFF342052))){Text(when{g.rematchRequestedByMe->"بانتظار موافقة الخصم…";g.rematchRequestedByOpponent->"قبول إعادة التحدي";else->"إعادة التحدي"},fontWeight=FontWeight.Bold)};if(g.rematchRequestedByOpponent&&!g.rematchRequestedByMe){Text("الخصم طلب إعادة التحدي",color=Color(0xFFB98CFF),fontSize=12.sp)};OutlinedButton(back,Modifier.fillMaxWidth()){Text("العودة للتحديات",color=ChallengeWhite)}}
